@startuml

class EBike {
  + frame : Frame
  + wheels : Wheel[]
  + driveSystem : DriveSystem
  + battery : Battery?
  + controller : Controller
  + connectBattery(battery : Battery)
  + disconnectBattery()
}

class Frame {
  + material : string
}

class Wheel {}

class DriveSystem {
  + motor : Motor
}

class Battery {
  + energy : double
}

abstract class Controller {
  + state : ControllerState
  + controlDriveSystem()
  + controlBattery(battery : Battery?)
}

enum ControllerState {
  On
  Off
  Charging
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + estimateNextInspectionDate() : Date
}

@enduml

